// E1b Mock (dry-run): dados de exemplo no formato das tabelas mkt_*
const C = '4a617a32-8493-4bd1-a9ab-12f5edf2055a';
return [{ json: { company_id: C,
  pieces: [{ id: 'p1', title: 'AI receptionist for tradies', status: 'published' }, { id: 'p2', title: 'Missed-call text-back in 30s', status: 'published' }, { id: 'p3', title: 'Quotes on autopilot', status: 'pending_approval' }],
  jobs: [{ id: 'j1', piece_id: 'p1', platform: 'instagram' }, { id: 'j2', piece_id: 'p1', platform: 'tiktok' }, { id: 'j3', piece_id: 'p2', platform: 'linkedin' }],
  metrics: [{ distribution_job_id: 'j1', captured_at: '2026-11-10', views: 1200, likes: 40, comments: 5, shares: 3, saves: 6 }, { distribution_job_id: 'j2', captured_at: '2026-11-10', views: 3400, likes: 120, comments: 12, shares: 9 }, { distribution_job_id: 'j3', captured_at: '2026-11-10', impressions: 800, likes: 15, clicks: 9 }],
  leads: [{ lead_table: 'lead_audits', utm_source: 'tiktok', utm_campaign: 'mkt_20261110_ai-receptionist', piece_id: 'p1' }, { lead_table: 'demo_requests', utm_source: 'linkedin', utm_campaign: 'mkt_20261110_missed-call', piece_id: 'p2' }],
  ideas: [{ id: 'i1', title: 'Boyd Group has AI agents booking repairs', source: 'google_news', score: 46, status: 'new' }] } }];

// E2 Análise semanal + página da manhã. Entrada: dados das tabelas mkt_* (ou mock). Sem rede.
const d = $input.first().json; const pieces = d.pieces || [], jobs = d.jobs || [], metrics = d.metrics || [], leads = d.leads || [], ideas = d.ideas || [];
const bne = new Date(Date.now() + 10 * 36e5); const today = bne.toISOString().slice(0, 10);
const start = new Date(bne.getTime() - 7 * 864e5).toISOString().slice(0, 10);
const lastByJob = {}; for (const m of metrics) if (!lastByJob[m.distribution_job_id] || m.captured_at > lastByJob[m.distribution_job_id].captured_at) lastByJob[m.distribution_job_id] = m;
const eng = m => (m.likes || 0) + 2 * (m.comments || 0) + 3 * (m.shares || 0) + 2 * (m.saves || 0) + 5 * (m.clicks || 0);
const byPiece = {};
for (const j of jobs) { const m = lastByJob[j.id] || {}; const b = byPiece[j.piece_id] = byPiece[j.piece_id] || { piece_id: j.piece_id, views: 0, engagement: 0, leads: 0, platforms: {} }; b.views += m.views || m.impressions || 0; b.engagement += eng(m); b.platforms[j.platform] = (b.platforms[j.platform] || 0) + eng(m); }
for (const l of leads) if (l.piece_id && byPiece[l.piece_id]) byPiece[l.piece_id].leads++;
const leadsByCampaign = {}; for (const l of leads) { const k = l.utm_campaign || '(sem utm)'; leadsByCampaign[k] = (leadsByCampaign[k] || 0) + 1; }
const leadsBySource = {}; for (const l of leads) { const k = l.utm_source || l.lead_table || 'direto'; leadsBySource[k] = (leadsBySource[k] || 0) + 1; }
const top = Object.values(byPiece).map(b => ({ ...b, title: (pieces.find(p => p.id === b.piece_id) || {}).title || b.piece_id, score: b.leads * 100 + b.engagement })).sort((a, b) => b.score - a.score).slice(0, 5);
const platTotals = {}; for (const b of Object.values(byPiece)) for (const [k, v] of Object.entries(b.platforms)) platTotals[k] = (platTotals[k] || 0) + v;
const bestPlat = Object.entries(platTotals).sort((a, b) => b[1] - a[1])[0]?.[0] || null;
const status = {}; for (const p of pieces) status[p.status] = (status[p.status] || 0) + 1;
const recs = [];
if (top[0]) recs.push(`Repetir o formato/tema de "${top[0].title}" (melhor da semana: ${top[0].leads} leads, engajamento ${top[0].engagement}).`);
if (bestPlat) recs.push(`Priorizar ${bestPlat} no horário nobre (maior engajamento somado).`);
if ((status.pending_approval || 0) > 3) recs.push(`${status.pending_approval} peças esperando aprovação — aprovar ou rejeitar no Telegram.`);
if (!leads.length) recs.push('Nenhum lead atribuído: conferir se os links levam UTM e se os formulários gravam a origem.');
const plan = ideas.filter(i => i.status === 'new').sort((a, b) => b.score - a.score).slice(0, 5).map((i, n) => ({ day: n + 1, idea_id: i.id, title: i.title, source: i.source }));
const stats = { pieces_by_status: status, distribution_jobs: jobs.length, leads: leads.length, leads_by_campaign: leadsByCampaign, leads_by_source: leadsBySource, platform_engagement: platTotals };
const md = [`# Página da manhã — Cytron Marketing (${today}, Brisbane)`, '', `**Semana ${start} → ${today}**`, `- Peças: ${Object.entries(status).map(([k, v]) => `${k} ${v}`).join(' · ') || 'nenhuma'}`,
  `- Posts distribuídos: ${jobs.length} · Leads atribuídos: ${leads.length}`, '', '## Top conteúdos', ...(top.length ? top.map((t, n) => `${n + 1}. ${t.title} — ${t.leads} leads, eng. ${t.engagement}`) : ['(sem métricas ainda)']),
  '', '## Recomendações', ...recs.map(r => '- ' + r), '', '## Plano da próxima semana (ideias com maior score)', ...(plan.length ? plan.map(p => `- Dia ${p.day}: ${p.title} (${p.source})`) : ['(sem ideias novas)'])].join('\n');
return [{ json: { insight: { company_id: d.company_id, period_start: start, period_end: today, kind: 'weekly', summary: recs.join(' '), stats, top_pieces: top, recommendations: recs, next_week_plan: plan, generator: 'heuristic_v1' }, morning_page_md: md } }];
